export declare function ShortcutModel(props?: Partial<{
    mode?: "normal" | "recording";
}>): {
    methods: {
        refresh(): void;
        register(handlers: Record<string, (event: KeyboardEvent_2 & {
            step?: "keydown" | "keyup";
        }) => void>): void;
        clearPressedKeys(): void;
        invokeHandlers(event: KeyboardEvent_2, key: string): void;
        buildShortcut(): {
            key1: string;
            key2: string;
        };
        setRecordingCodes(codes: string): void;
        reset(): void;
        testShortcut(opt: {
            /** 存在 pressing 时，进行拼接后的字符串，用于「组合快捷键」 */
            key1: string;
            /** 没有其他出于 pressing 状态的情况下，按下的按键拼接后的字符串，用于「单个快捷键或连按」 */
            key2: string;
            step: "keydown" | "keyup";
        }, event: KeyboardEvent_2): void;
        handleKeydown(event: {
            code: string;
            preventDefault: () => void;
        }): void;
        handleKeyup(event: {
            code: string;
            preventDefault: () => void;
        }, opt?: Partial<{
            fake: boolean;
        }>): void;
    };
    ui: {};
    state: {
        readonly codes: string[];
        readonly codes2: string[];
    };
    ready(): void;
    destroy(): void;
    onShortcut(handler: Handler<{
        key: string;
    }>): () => void;
    onShortcutComplete(handler: Handler<{
        codes: string[];
    }>): () => void;
    onStateChange(handler: Handler<{
        readonly codes: string[];
        readonly codes2: string[];
    }>): () => void;
    onError(handler: Handler<BizError>): () => void;
};

